solution.solution.py:
def add_bits(a, b):
    out = []
    carry = 0
    for x, y in zip(reversed(a), reversed(b)):
        total = int(x) + int(y) + carry
        out.append(str(total % 2))
        carry = total // 2
    return "".join(reversed(out))

def negate(pattern):
    flipped = "".join("1" if ch == "0" else "0" for ch in pattern)
    one = "0" * (len(pattern) - 1) + "1"
    return add_bits(flipped, one)

def signed_value(pattern):
    value = 0
    for ch in pattern:
        value = value * 2 + int(ch)
    if pattern[0] == "1":
        value -= 2 ** len(pattern)
    return value

unitTests:
@test("adding with carries")
def _():
    check_eq(add_bits("01011", "00111"), "10010")
    check_eq(add_bits("0110", "0011"), "1001")
    check_eq(add_bits("0000", "0000"), "0000")

@test("overflow drops the last carry")
def _():
    check_eq(add_bits("11111111", "00000001"), "00000000")
    check_eq(add_bits("11001000", "01100100"), "00101100")

@test("negating")
def _():
    check_eq(negate("00000101"), "11111011")
    check_eq(negate("11111011"), "00000101")
    check_eq(negate("00000001"), "11111111")
    check_eq(negate("00000000"), "00000000")

@test("signed readings")
def _():
    check_eq(signed_value("00000101"), 5)
    check_eq(signed_value("11111011"), -5)
    check_eq(signed_value("11111111"), -1)
    check_eq(signed_value("01111111"), 127)
    check_eq(signed_value("10000000"), -128)
    check_eq(signed_value("1000000000000000"), -32768)

@test("subtraction is adding the negation")
def _():
    check_eq(signed_value(add_bits("00000111", negate("00000101"))), 2)
    check_eq(signed_value(add_bits("00000011", negate("00001000"))), -5)

